describe('Browser Back Button Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate back without losing app state', () => {
    // Navigate to a detail page
    cy.get('[data-testid="nav-to-profile"]').click();
    cy.url().should('include', '/profile');

    // Perform an action on the detail page
    cy.get('[data-testid="edit-profile-btn"]').click();
    cy.get('[data-testid="profile-form"]').should('be.visible');
    cy.get('[data-testid="name-input"]').type('John Doe');

    // Navigate back using browser back button
    cy.go('back');
    cy.url().should('include', '/dashboard');

    // Verify app state is preserved
    cy.get('[data-testid="profile-card"]').should('be.visible');
    cy.get('[data-testid="profile-card"]').should('contain', 'John Doe');

    // Verify the user is still on the dashboard
    cy.get('[data-testid="dashboard-stats"]').should('be.visible');
  });

  it('should handle back button when no previous page exists', () => {
    // Navigate to a page
    cy.get('[data-testid="nav-to-settings"]').click();
    cy.url().should('include', '/settings');

    // Navigate to another page
    cy.get('[data-testid="nav-to-billing"]').click();
    cy.url().should('include', '/billing');

    // Navigate back to settings
    cy.go('back');
    cy.url().should('include', '/settings');

    // Navigate back to dashboard
    cy.go('back');
    cy.url().should('include', '/dashboard');

    // Attempt to navigate back when on the initial page
    cy.go('back');
    cy.url().should('eq', '/dashboard');

    // Verify app state is still intact on the initial page
    cy.get('[data-testid="dashboard-stats"]').should('be.visible');
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Total Users');
  });
});
